import 'jest';
import { getEnvironment, getForEnvironment, getPoweredByTombolaEnvironment, isEnvironmentSetting } from '../../src';

const originalLocation = window.location;

describe('getEnvironment()', () => {
    beforeEach(() => {
        // @ts-ignore
        delete window.location;
    });

    afterEach(() => {
        window.location = originalLocation;
    });

    it('will identify debug environments', () => {
        window.location = { ...originalLocation, hostname: 'http://192.168.1.1:9001', origin: 'http://192.168.1.1:9001' };
        expect(getEnvironment()).toEqual('debug');
    });

    describe('for arcade URLs', () => {
        it('will identify dev environments', () => {
            window.location = { ...originalLocation, hostname: 'https://dev-desktop.tombolaarcade.co.uk', origin: 'https://dev-desktop.tombolaarcade.co.uk' };
            expect(getEnvironment()).toEqual('dev');
        });

        it('will identify stage environments', () => {
            window.location = { ...originalLocation, hostname: 'https://stage-desktop.tombolaarcade.co.uk', origin: 'https://stage-desktop.tombolaarcade.co.uk' };
            expect(getEnvironment()).toEqual('stage');
        });

        it('will identify live environments', () => {
            window.location = { ...originalLocation, hostname: 'https://desktop.tombolaarcade.co.uk', origin: 'https://desktop.tombolaarcade.co.uk' };
            expect(getEnvironment()).toEqual('live');
        });
    });

    describe('for bingo URLs', () => {
        it('will identify dev environments', () => {
            window.location = { ...originalLocation, hostname: 'https://dev-client.tombola.co.uk', origin: 'https://dev-client.tombola.co.uk' };
            expect(getEnvironment()).toEqual('dev');
        });

        it('will identify stage environments', () => {
            window.location = { ...originalLocation, hostname: 'https://stage-client.tombola.co.uk', origin: 'https://stage-client.tombola.co.uk' };
            expect(getEnvironment()).toEqual('stage');
        });

        it('will identify live environments', () => {
            window.location = { ...originalLocation, hostname: 'https://client.tombola.co.uk', origin: 'https://client.tombola.co.uk' };
            expect(getEnvironment()).toEqual('live');
        });
    });

    describe('for Spanish URLs', () => {
        it('will identify dev environments', () => {
            window.location = { ...originalLocation, hostname: 'https://dev-gameclients.tombola.es', origin: 'https://dev-gameclients.tombola.es' };
            expect(getEnvironment()).toEqual('dev');
        });

        it('will identify stage environments', () => {
            window.location = { ...originalLocation, hostname: 'https://stage-gameclients.tombola.es', origin: 'https://stage-gameclients.tombola.es' };
            expect(getEnvironment()).toEqual('stage');
        });

        it('will identify live environments', () => {
            window.location = { ...originalLocation, hostname: 'https://gameclients.tombola.es', origin: 'https://gameclients.tombola.es' };
            expect(getEnvironment()).toEqual('live');
        });
    });

    describe('for Italian URLs', () => {
        it('will identify dev environments', () => {
            window.location = { ...originalLocation, hostname: 'https://dev-gameclients.tombola.it', origin: 'https://dev-gameclients.tombola.it' };
            expect(getEnvironment()).toEqual('dev');
        });

        it('will identify stage environments', () => {
            window.location = { ...originalLocation, hostname: 'https://stage-gameclients.tombola.it', origin: 'https://stage-gameclients.tombola.it' };
            expect(getEnvironment()).toEqual('stage');
        });

        it('will identify live environments', () => {
            window.location = { ...originalLocation, hostname: 'https://gameclients.tombola.it', origin: 'https://gameclients.tombola.it' };
            expect(getEnvironment()).toEqual('live');
        });
    });

    describe('for Swedish URLs', () => {
        it('will identify dev environments', () => {
            window.location = { ...originalLocation, hostname: 'https://dev-gameclients.tombola.se', origin: 'https://dev-gameclients.tombola.se' };
            expect(getEnvironment()).toEqual('dev');
        });

        it('will identify stage environments', () => {
            window.location = { ...originalLocation, hostname: 'https://stage-gameclients.tombola.se', origin: 'https://stage-gameclients.tombola.se' };
            expect(getEnvironment()).toEqual('stage');
        });

        it('will identify live environments', () => {
            window.location = { ...originalLocation, hostname: 'https://gameclients.tombola.se', origin: 'https://gameclients.tombola.se' };
            expect(getEnvironment()).toEqual('live');
        });
    });

    describe('for Danish URLs', () => {
        it('will identify dev environments', () => {
            window.location = { ...originalLocation, hostname: 'https://dev-gameclients.tombola.dk', origin: 'https://dev-gameclients.tombola.dk' };
            expect(getEnvironment()).toEqual('dev');
        });

        it('will identify stage environments', () => {
            window.location = { ...originalLocation, hostname: 'https://stage-gameclients.tombola.dk', origin: 'https://stage-gameclients.tombola.dk' };
            expect(getEnvironment()).toEqual('stage');
        });

        it('will identify live environments', () => {
            window.location = { ...originalLocation, hostname: 'https://gameclients.tombola.dk', origin: 'https://gameclients.tombola.dk' };
            expect(getEnvironment()).toEqual('live');
        });
    });

    describe('for Dutch URLs', () => {
        it('will identify dev environments', () => {
            window.location = { ...originalLocation, hostname: 'https://gameclients.dev.tombola.nl', origin: 'https://gameclients.dev.tombola.nl' };
            expect(getEnvironment()).toEqual('dev');
        });

        it('will identify stage environments', () => {
            window.location = { ...originalLocation, hostname: 'https://gameclients.stage.tombola.nl', origin: 'https://gameclients.stage.tombola.nl' };
            expect(getEnvironment()).toEqual('stage');
        });

        it('will identify live environments', () => {
            window.location = { ...originalLocation, hostname: 'https://gameclients.tombola.nl', origin: 'https://gameclients.tombola.nl' };
            expect(getEnvironment()).toEqual('live');
        });
    });

    describe('isEnvironmentSetting()', () => {
        it('will return false if the config is not an object', () => {
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            expect(isEnvironmentSetting('wrong' as any)).toBe(false);
        });

        it('will return true if the config is an object with environment keys', () => {
            expect(isEnvironmentSetting({
                debug: {},
                dev: {},
                stage: {},
                live: {}
            })).toBe(true);
        });
    });


    describe('getForEnvironment()', () => {
        it('will throw an exception if the config is not an object', () => {
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            expect(() => getForEnvironment('wrong' as any)).toThrow();
        });

        it('will identify debug environments', () => {
            window.location = { ...originalLocation, hostname: 'http://192.168.1.1:9001', origin: 'http://192.168.1.1:9001' };
            expect(getForEnvironment({
                debug: true,
                dev: false,
                stage: false,
                live: false
            })).toEqual(true);
        });

        it('will identify dev environments', () => {
            window.location = { ...originalLocation, hostname: 'https://dev-client.tombola.co.uk', origin: 'https://dev-client.tombola.co.uk' };
            expect(getForEnvironment({
                debug: false,
                dev: true,
                stage: false,
                live: false
            })).toEqual(true);
        });

        it('will identify stage environments', () => {
            window.location = { ...originalLocation, hostname: 'https://stage-client.tombola.co.uk', origin: 'https://stage-client.tombola.co.uk' };
            expect(getForEnvironment({
                debug: false,
                dev: false,
                stage: true,
                live: false
            })).toEqual(true);
        });

        it('will identify live environments', () => {
            window.location = { ...originalLocation, hostname: 'https://client.tombola.co.uk', origin: 'https://client.tombola.co.uk' };
            expect(getForEnvironment({
                debug: false,
                dev: false,
                stage: false,
                live: true
            })).toEqual(true);
        });
    });

    describe('for poweredbytombola URLs', () => {
        it('will identify old style environments', () => {
            window.location = { ...originalLocation, hostname: 'https://game-sisal.dev.poweredbytombola.co.uk', origin: 'https://game-sisal.dev.poweredbytombola.co.uk' };
            expect(getEnvironment()).toEqual('dev');
        });

        it('will isolate the operator, environment and locale suffix', () => {
            window.location = { ...originalLocation, hostname: 'https://game-sisal.integration.poweredbytombola.dk', origin: 'https://game-sisal.integration.poweredbytombola.dk' };
            const { environment, operator, topLevelDomain } = getPoweredByTombolaEnvironment('co.uk', 'tombola');
            expect(environment).toEqual('integration');
            expect(operator).toEqual('sisal');
            expect(topLevelDomain).toEqual('dk');
        });
    });
});
